 "content": "from collections import Counter


def transform(grid):
    """Fill gaps between consecutive marker cells in each row and column."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    marker = next(v for v, _ in counts.most_common() if v != background)

    for r in range(h):
        marks = [c for c in range(w) if grid[r][c] == marker]
        for a, b in zip(marks, marks[1:]):
            for c in range(a + 1, b):
                if grid[r][c] == background:
                    out[r][c] = 3

    for c in range(w):
        marks = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(marks, marks[1:]):
            for r in range(a + 1, b):
                if grid[r][c] == background:
                    out[r][c] = 3
    return out


if __name__ == '__main__':
    demo = [
        [8,8,8,6], [8,8,8,6], [6,8,8,8], [8,8,8,8], [6,8,8,6],
        [8,8,8,6], [8,6,8,8], [6,8,8,8], [8,6,8,8], [8,6,8,8],
    ]
    expected = [
        [8,8,8,6], [8,8,8,6], [6,8,8,3], [3,8,8,3], [6,3,3,6],
        [3,8,8,6], [3,6,8,8], [6,3,8,8], [8,6,8,8], [8,6,8,8],
    ]
    assert transform(demo) == expected
    test = [
