        [2,5,2,5,2,5,5,5,5,5,5,2,5,5,5,5,5,5,5,5,2,5,5,5],
    ]
    result = transform(test)
    assert len(result) == 7 and all(len(row) == 24 for row in result)
    import json
    print(json.dumps(result))
    print('demo validation passed')
